@extends('layouts.app') @section('title','Find Jobs — AXOS') @section('content')<div class="container"><h1>Find Jobs</h1><p class="muted">Search opportunities published by employers.</p><form class="card" style="margin:20px 0"><div class="grid"><input class="input" name="search" placeholder="Search jobs" value="{{request('search')}}"><input class="input" name="location" placeholder="Location" value="{{request('location')}}"><input class="input" name="category" placeholder="Category" value="{{request('category')}}"><select name="employment_type"><option value="">Any employment type</option>@foreach(['full_time'=>'Full time','part_time'=>'Part time','contract'=>'Contract','internship'=>'Internship','temporary'=>'Temporary'] as $k=>$v)<option value="{{$k}}" @selected(request('employment_type')===$k)>{{$v}}</option>@endforeach</select></div><br><label><input type="checkbox" name="remote" value="1" @checked(request('remote'))> Remote only</label><br><br><button class="btn">Search</button></form><div class="grid">@forelse($q as $job)<a class="card" href="{{route('jobs.show',$job)}}"><div class="job"><div><h2 style="margin-top:0">{{$job->title}}</h2><p class="muted">{{$job->employerProfile?->company_name ?? $job->employer->name}}</p><p class="muted">{{$job->location ?: 'Location not specified'}} · {{str_replace('_',' ',ucfirst($job->employment_type))}}</p></div>@if($job->remote)<span class="badge">Remote</span>@endif</div></a>@empty<div class="card">No jobs found.</div>@endforelse</div><div style="margin-top:25px">{{$q->links()}}</div></div>@endsection